{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "Retain an appropriate general-warranty cap only, but exclude or separately cap"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Negotiate lower figures and ensure the basket is not applied to tax, title, capacity, indemnities, fraud or deliberate breach."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PARTIAL",
      "evidence": "General business warranties may have a negotiated survival period"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "fundamental title/capacity protections outside the general limitations"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "exclude or separately cap title, capacity, tax, fraud, wilful misconduct, specific indemnities and restrictive covenant claims"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket disclosure. Disclosure must be specific, fair, sufficiently detailed and cross-referenced to the warranty it qualifies"
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete constructive knowledge/discoverability."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "no deemed satisfaction merely upon delivery of an incomplete consent"
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "simultaneous irrevocable discharge/release documentation at Completion"
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "itemise them in funds flow; require Seller to pay them or reduce price dollar-for-dollar"
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "A narrow indemnity for one payment is not an adequate substitute for clean ownership of core IP."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Seek a specific indemnity, covenant to conduct and fund pre-Completion remediation, and a holdback or price adjustment"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Treat non-ordinary-course, non-budgeted, related-party, prepaid or non-terminable commitments as restricted actions, leakage or a price adjustment as appropriate."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Do not accept the Seller’s attempt to put virtually every risk"
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "A share register alone is not adequate protection"
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "The IP warranties should remain outside the general liability regime or have a materially higher dedicated cap and longer survival."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": true
}

